DO $guard$ BEGIN IF NOT EXISTS (SELECT 1 FROM lr_questions q WHERE q.qid=$batch07$PT107-S1-Q8$batch07$ AND q.stimulus=$batch07$Nutritionist: Many people claim that simple carbohydrates are a reasonable caloric replacement for the fatty foods forbidden to those on low-fat diets. This is now in doubt. New studies show that, for many people, a high intake of simple carbohydrates stimulates an overproduction of insulin, a hormone that is involved in processing sugars and starches to create energy when the body requires energy, or, when energy is not required, to store the resulting by-products as fat.$batch07$ AND q.prompt=$batch07$Which one of the following is most strongly supported by the nutritionist's statements?$batch07$ AND q.correct_choice=$batch07$D$batch07$) THEN RAISE EXCEPTION 'Question changed: PT107-S1-Q8'; END IF; END $guard$;
DO $guard$ BEGIN IF (SELECT COUNT(*) FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id WHERE q.qid=$batch07$PT107-S1-Q8$batch07$ AND e.style IN ('single','standard')) <> 0 THEN RAISE EXCEPTION 'Explanation row changed: PT107-S1-Q8'; END IF; END $guard$;
INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch07$PT107-S1-Q8$batch07$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch07$Statements$batch07$, $batch07$People say simple carbs are a good substitute for the fatty foods a low-fat diet forbids. That is now in doubt. For many people, a high intake of simple carbs causes too much insulin. Insulin turns sugars into energy when the body needs it, and stores the by-products as fat when it doesn't.$batch07$), (1, $batch07$Evaluate$batch07$, $batch07$Pause and infer. Follow the chain: lots of simple carbs → too much insulin → when energy isn't needed, the by-products get stored as fat. So eating lots of simple carbs can make you store fat. That is why swapping fat for simple carbs is "in doubt".$batch07$), (2, $batch07$Goal$batch07$, $batch07$If you want to avoid gaining fat, go easy on simple carbs.$batch07$)) v(position,label,body) WHERE q.qid=$batch07$PT107-S1-Q8$batch07$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch07$A$batch07$, $batch07$This is the most popular wrong answer. The passage never says simple carbs reduce your energy. Insulin *creates* energy when the body needs it. The problem is the extra fat stored when it doesn't.$batch07$), ($batch07$B$batch07$, $batch07$The passage says nothing about who should or shouldn't adopt a low-fat diet.$batch07$), ($batch07$C$batch07$, $batch07$The passage is about cutting simple carbs, not cutting fat.$batch07$), ($batch07$D$batch07$, $batch07$High simple carbs → too much insulin → fat storage. So limiting simple carbs is a reasonable way to avoid gaining body fat.$batch07$), ($batch07$E$batch07$, $batch07$"Will not lose weight" is far stronger than anything here. The passage doesn't talk about losing weight at all.$batch07$)) v(letter,body) WHERE q.qid=$batch07$PT107-S1-Q8$batch07$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id AND n.letter=v.letter) ON CONFLICT DO NOTHING;
